"""CLI subcommand: flow-props init"""

from __future__ import annotations

from pathlib import Path

import typer

# -- BL-only template (written by: flow-props init --bl) --
BL_TEMPLATE = """\
#--------------------------------------------------
# flow-props BL configuration
# generated by: flow-props init --bl
# run with:     flow-props run --bl
#--------------------------------------------------

#--------------------------------------------------
# input
#--------------------------------------------------
# CFD solution file.
fname = "base_flow.hdf5"
# For split file formats, uncomment and set the separate grid file.
# gname = "grid.s8"

#--------------------------------------------------
# station selection
#--------------------------------------------------
# Leave this table empty to process all i-stations (0 through Nx - 1, step 1).
# To select fewer stations, uncomment exactly one mode below.
[stations]
# Mode 1: sample wall x-coordinates from x_s to x_e, inclusive.
# Start x [m].
# x_s = 0.05
# End x [m].
# x_e = 0.50
# Spacing between requested x-coordinates [m].
# dx  = 0.05

# Mode 2: select i-indices from i_s to i_e, inclusive, with step di.
# i_s = 10
# i_e = 500
# di  = 10

# Mode 3: select only these i-indices.
# list = [10, 50, 100, 200]

#--------------------------------------------------
# boundary layer extraction
#--------------------------------------------------
[bl]
# Edge criterion: velocity_ratio or htot_derivative.
criterion = "velocity_ratio"
# Fraction of edge velocity for velocity_ratio.
threshold = 0.99
# Tecplot ASCII BL property table.
output = "bl_properties.dat"
# Tecplot ASCII wall-normal profiles; omit this setting to skip profile output.
profiles_output = "bl_profiles.dat"

#--------------------------------------------------
# optional gas overrides (otherwise read HDF5 attrs or flow_conditions.json)
#--------------------------------------------------
# [gas]
# gamma        = 1.4
# gas_constant = 287.05
"""

# -- full template (written by: flow-props init) --
FULL_TEMPLATE = """\
#--------------------------------------------------
# flow-props configuration
# generated by: flow-props init
# run with:     flow-props run
# Tip: for BL-only runs use: flow-props init --bl  ->  bl.toml
#--------------------------------------------------

#--------------------------------------------------
# input
#--------------------------------------------------
# CFD solution file.
fname = "base_flow.hdf5"
# For split file formats, uncomment and set the separate grid file.
# gname = "grid.s8"

#--------------------------------------------------
# station selection
#--------------------------------------------------
# Leave this table empty to process all i-stations (0 through Nx - 1, step 1).
# To select fewer stations, uncomment exactly one mode below.
[stations]
# Mode 1: sample wall x-coordinates from x_s to x_e, inclusive.
# Start x [m].
# x_s = 0.05
# End x [m].
# x_e = 0.50
# Spacing between requested x-coordinates [m].
# dx  = 0.05

# Mode 2: select i-indices from i_s to i_e, inclusive, with step di.
# i_s = 10
# i_e = 500
# di  = 10

# Mode 3: select only these i-indices.
# list = [10, 50, 100, 200]

#--------------------------------------------------
# boundary layer extraction
#--------------------------------------------------
[bl]
# Edge criterion: velocity_ratio or htot_derivative.
criterion = "velocity_ratio"
# Fraction of edge velocity for velocity_ratio.
threshold = 0.99
# Tecplot ASCII BL property table.
output = "bl_properties.dat"
# Tecplot ASCII wall-normal profiles; omit this setting to skip profile output.
profiles_output = "bl_profiles.dat"

#--------------------------------------------------
# optional gas overrides (otherwise read HDF5 attrs or flow_conditions.json)
#--------------------------------------------------
# [gas]
# gamma        = 1.4
# gas_constant = 287.05
"""


def cmd_init(
    bl: bool = typer.Option(False, "--bl", help="Write BL-only config (bl.toml)."),
    force: bool = typer.Option(False, "--force", help="Overwrite existing config."),
) -> None:
    """Write a default config file in the current directory.

    Without flags: writes flow_props.toml (full template).
    With --bl:     writes bl.toml (BL extraction only).
    """
    # select template and filename based on mode
    if bl:
        dest = Path("bl.toml")
        template = BL_TEMPLATE
        run_hint = "flow-props run --bl"
    else:
        dest = Path("flow_props.toml")
        template = FULL_TEMPLATE
        run_hint = "flow-props run"

    # check target path
    if dest.exists() and not force:
        typer.echo(f"Error: {dest} already exists. Use --force to overwrite.", err=True)
        raise typer.Exit(code=1)

    # write template
    dest.write_text(template, encoding="utf-8")
    typer.echo(f"Written {dest}")
    typer.echo(f"Edit the file then run:  {run_hint}")
